  aside > div + div { margin-top: 0; padding-top: 0; border-top: 0; }
  header { gap: 12px; padding: 12px 14px; }
  h1 { font-size: 21px; }
  .stats { flex: 1 1 100%; gap: 6px; }
  .stats > div { flex: 1 1 auto; min-width: 58px; padding: 6px 9px; }
  .stats b { font-size: 14px; }
  .modal { padding: 20px; }
  .modal h2 { font-size: 28px; }
  .hint { font-size: 12px; }
}
@media (max-width: 560px) {
  main { padding: 7px; gap: 10px; }
  header { padding: 12px; }
  .stats { font-size: 11px; }
  .stats > div { padding: 6px 7px; }
  .stats b { font-size: 13px; margin-left: 3px; }
  aside { display: block; padding: 14px; }
  aside > div + div { margin-top: 22px; padding-top: 20px; border-top: 1px solid #47604f; }
  .ribbon { padding: 9px 11px; font-size: 11px; }
  .modal { padding: 16px; }
  .modal .quick-missions { padding: 11px; }
  input[type="text"], input[type="number"], select { font-size: 16px; }
  .coordinate-aid-bar { padding: 10px; }
  .coordinate-aid-bar button { white-space: normal; }
  #mapCommandReceipt { padding: 10px 11px; font-size: 12px; }
}
@media (pointer: coarse) {
  button, .mini button, .coordinate-aid-bar button, select, input[type="text"], input[type="number"] { min-height: 44px; }
  aside details > summary { padding-block: 7px; }
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }
